-- Catalog sync: every product in data/products.js. Generated by scripts/build.js; don't edit. Applied by the deploy
-- (and scripts/dev.js locally) after the migrations. Re-applying it is harmless.
INSERT INTO products (id, title, description, type, price_cents, currency, artwork, preview, tags, release_id, metadata, featured, published, max_quantity, project_id, pacs, catalog_hash, created_at, updated_at) VALUES ('sample-pack-vol1', 'Frayed Signals — Sample Pack Vol. 1', '300+ one-shots, glitch loops, bit-crushed vocal chops and stitched-together drum fills. WAV, 24-bit.', 'sample-pack', 2499, 'USD', NULL, NULL, '["wav","one-shots","loops"]', NULL, '{"hue":300}', 1, 0, 1, 'glitches-and-stitches', '["frayed-signals-samples","frayed-signals-loops"]', '5b54a1e5e55e7cd6', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'))
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, description = excluded.description, type = excluded.type, price_cents = excluded.price_cents, currency = excluded.currency, artwork = excluded.artwork, preview = excluded.preview, tags = excluded.tags, release_id = excluded.release_id, metadata = excluded.metadata, featured = excluded.featured, published = excluded.published, max_quantity = excluded.max_quantity, project_id = excluded.project_id, pacs = excluded.pacs, catalog_hash = excluded.catalog_hash, deleted_at = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE products.source = 'catalog' AND products.admin_managed = 0 AND (products.catalog_hash IS NOT excluded.catalog_hash OR products.deleted_at IS NOT NULL);
